using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    // Approved: a Gold customer with a 100.00 subtotal pays 95.00.
    // No checkout API exists yet, so this probes the production assemblies for one.
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPayableTotal95()
    {
        var checkoutTypes = new[] { typeof(ApplicationMarker).Assembly, typeof(DomainMarker).Assembly }
            .SelectMany(a => a.GetTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing") || t.Name.Contains("Discount"))
            .ToList();

        Assert.True(checkoutTypes.Count > 0, "No checkout/pricing/discount type exists; cannot compute a payable total (expected 95.00 for Gold, 100.00 subtotal).");
    }
}
